// The TS port against the C# engine: every golden case (generated by
// scripts/duel-golden from CosQuest.Duel) replayed tick for tick, with the
// hash at every checkpoint, the final state, the event stream, the wire log,
// the verifier's replay and the server-setup mapping all compared exactly.
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { describe, it } from "node:test";

import { Fnv1a } from "../determinism.ts";
import { DuelSim } from "../duelSim.ts";
import { InputLog, type WireInput } from "../inputLog.ts";
import { finishPayload, finishJson } from "../runner.ts";
import {
  AiParams,
  DuelSetup,
  FighterSetup,
  FighterStats,
  presentationFromServer,
  setupFromServer,
} from "../setup.ts";
import type { FighterState } from "../state.ts";
import type { Difficulty, Faction, InputKind, SpecialUse, Stance, WeaponClass } from "../types.ts";

interface AiJson {
  reactionTicks: number;
  aggression: number;
  blockBias: number;
  dodgeBias: number;
  chainChance: number;
  mistakePermille: number;
  specialUse: number;
  stance: number;
  faction: number;
}
interface FighterSetupJson {
  name: string;
  class: number;
  stats: { maxHp: number; attack: number; mitigationPermille: number };
  ai: AiJson | null;
}
interface SetupJson {
  seed: string;
  roundTicks: number;
  arenaHalfWidthMm: number;
  startGapMm: number;
  p1: FighterSetupJson;
  p2: FighterSetupJson;
}
type FighterJson = Record<string, number | boolean>;
interface GoldenCase {
  name: string;
  note?: string;
  setup: SetupJson;
  ai1Create?: [number, number, number];
  ai2Create?: [number, number, number];
  server?: { json: string; seedText: string; presentation: Record<string, string | number> };
  styles: [string, string];
  maxTicks: number;
  wire: { p1: WireInput[]; p2: WireInput[] };
  checkpoints: [number, string][];
  final: {
    tick: number;
    ticksLeft: number;
    hitStop: number;
    over: boolean;
    winner: number;
    endReason: number;
    hash: string;
    eventsHash: string;
    eventCount: number;
    eventCounts: number[];
    p1: FighterJson;
    p2: FighterJson;
  };
  replay?: { hash: string; winner: number; ticks: number; p1Hp: number; p2Hp: number; endReason: number };
  finishJson?: string;
}
interface Golden {
  version: number;
  engine: { sourcesSha256: string; lastCommit: string | null };
  checkpointEvery: number;
  cases: GoldenCase[];
}

const golden = JSON.parse(readFileSync(new URL("./golden.json", import.meta.url), "utf8")) as Golden;

function aiFrom(j: AiJson | null): AiParams | null {
  if (j == null) return null;
  const a = new AiParams();
  a.reactionTicks = j.reactionTicks;
  a.aggression = j.aggression;
  a.blockBias = j.blockBias;
  a.dodgeBias = j.dodgeBias;
  a.chainChance = j.chainChance;
  a.mistakePermille = j.mistakePermille;
  a.specialUse = j.specialUse as SpecialUse;
  a.stance = j.stance as Stance;
  a.faction = j.faction as Faction;
  return a;
}

function fighterFrom(j: FighterSetupJson): FighterSetup {
  const f = new FighterSetup();
  f.name = j.name;
  f.class = j.class as WeaponClass;
  f.stats = new FighterStats(j.stats.maxHp, j.stats.attack, j.stats.mitigationPermille);
  f.ai = aiFrom(j.ai);
  return f;
}

export function setupFrom(j: SetupJson): DuelSetup {
  const s = new DuelSetup();
  s.seed = BigInt(j.seed);
  s.roundTicks = j.roundTicks;
  s.arenaHalfWidthMm = j.arenaHalfWidthMm;
  s.startGapMm = j.startGapMm;
  s.p1 = fighterFrom(j.p1);
  s.p2 = fighterFrom(j.p2);
  return s;
}

function aiToJson(a: AiParams | null): AiJson | null {
  return a == null ? null : {
    reactionTicks: a.reactionTicks,
    aggression: a.aggression,
    blockBias: a.blockBias,
    dodgeBias: a.dodgeBias,
    chainChance: a.chainChance,
    mistakePermille: a.mistakePermille,
    specialUse: a.specialUse,
    stance: a.stance,
    faction: a.faction,
  };
}

/** The setup in the golden's JSON shape, to compare a mapped setup field by field. */
function setupToJson(s: DuelSetup): SetupJson {
  const f = (x: FighterSetup): FighterSetupJson => ({
    name: x.name,
    class: x.class,
    stats: { maxHp: x.stats.maxHp, attack: x.stats.attack, mitigationPermille: x.stats.mitigationPermille },
    ai: aiToJson(x.ai),
  });
  return {
    seed: s.seed.toString(),
    roundTicks: s.roundTicks,
    arenaHalfWidthMm: s.arenaHalfWidthMm,
    startGapMm: s.startGapMm,
    p1: f(s.p1),
    p2: f(s.p2),
  };
}

function fighterJson(f: FighterState): FighterJson {
  return {
    x: f.x, facing: f.facing, action: f.action, actionTick: f.actionTick, actionLength: f.actionLength,
    actionStartup: f.actionStartup, move: f.move, hp: f.hp, meter: f.meter, guard: f.guard, hitStop: f.hitStop,
    holding: f.holding, holdTicks: f.holdTicks, chargeTicks: f.chargeTicks, comboStep: f.comboStep,
    hitThisAction: f.hitThisAction, hitConnected: f.hitConnected, buffered: f.buffered, bufferAge: f.bufferAge,
    lastInput: f.lastInput, invulnerable: f.invulnerable, inActiveFrames: f.inActiveFrames, hpPermille: f.hpPermille,
  };
}

/** A side's wire log expanded to one input per tick (what the script pressed). */
function expand(wire: WireInput[]): Map<number, InputKind> {
  const m = new Map<number, InputKind>();
  for (const e of wire) {
    const n = e.length === 3 ? e[2] : 1;
    for (let t = 0; t < n; t++) m.set(e[0] + t, e[1] as InputKind);
  }
  return m;
}

function play(c: GoldenCase, setup: DuelSetup) {
  const sim = new DuelSim(setup);
  const log = new InputLog();
  const in1 = expand(c.wire.p1);
  const in2 = expand(c.wire.p2);
  const checkpoints = new Map(c.checkpoints);
  const ev = new Fnv1a();
  const counts = new Array<number>(10).fill(0);
  let eventCount = 0;
  const firstCheck = c.checkpoints[0];
  assert.equal(firstCheck[0], 0);
  assert.equal(sim.hashHex(), firstCheck[1], `${c.name}: hash before the first tick`);
  let checked = 1;
  while (!sim.state.over && sim.state.tick < c.maxTicks) {
    const t = sim.state.tick + 1;
    InputLog.step(sim, log, in1.get(t) ?? 0, in2.get(t) ?? 0);
    for (const e of sim.drainEvents()) {
      ev.addInt(e.type); ev.addInt(e.tick); ev.addInt(e.source); ev.addInt(e.target);
      ev.addInt(e.move); ev.addInt(e.damage); ev.addInt(e.hitStop); ev.addInt(e.x);
      counts[e.type]++;
      eventCount++;
    }
    const want = checkpoints.get(t);
    if (want !== undefined) {
      // Fail at the first divergent checkpoint, naming the tick.
      assert.equal(sim.hashHex(), want, `${c.name}: hash at tick ${t}`);
      checked++;
    }
  }
  assert.equal(checked, c.checkpoints.length, `${c.name}: every checkpoint was reached`);
  return { sim, log, eventsHash: ev.hex, counts, eventCount };
}

describe("golden vectors from the C# engine", () => {
  it("has the cases the generator promises", () => {
    assert.equal(golden.version, 1);
    assert.ok(golden.cases.length >= 40, `${golden.cases.length} cases`);
    const classes = new Set(golden.cases.flatMap((c) => [c.setup.p1.class, c.setup.p2.class]));
    assert.deepEqual([...classes].sort(), [0, 1, 2, 3, 4]);
    const ends = new Set(golden.cases.map((c) => `${c.final.endReason}:${c.final.winner}`));
    for (const e of ["1:1", "1:2", "1:0", "2:1", "2:2", "2:0"]) assert.ok(ends.has(e), `an ending ${e}`);
    const kinds = new Set(golden.cases.flatMap((c) => [...c.wire.p1, ...c.wire.p2].map((w) => w[1])));
    for (let k = 1; k <= 9; k++) assert.ok(kinds.has(k), `input code ${k} is exercised`);
    assert.ok(golden.cases.filter((c) => c.server).length >= 5, "server-setup cases");
  });

  for (const c of golden.cases) {
    it(`${c.name}`, () => {
      const setup = setupFrom(c.setup);
      if (c.ai1Create) assert.deepEqual(aiToJson(AiParams.create(...(c.ai1Create as [Stance, Faction, Difficulty]))), c.setup.p1.ai, "AiParams.create for P1");
      if (c.ai2Create) assert.deepEqual(aiToJson(AiParams.create(...(c.ai2Create as [Stance, Faction, Difficulty]))), c.setup.p2.ai, "AiParams.create for P2");

      const { sim, log, eventsHash, counts, eventCount } = play(c, setup);
      const s = sim.state;
      const f = c.final;
      assert.deepEqual(
        { tick: s.tick, ticksLeft: s.ticksLeft, hitStop: s.hitStop, over: s.over, winner: s.winner, endReason: s.endReason },
        { tick: f.tick, ticksLeft: f.ticksLeft, hitStop: f.hitStop, over: f.over, winner: f.winner, endReason: f.endReason },
      );
      assert.deepEqual(fighterJson(s.p1), f.p1, "final P1");
      assert.deepEqual(fighterJson(s.p2), f.p2, "final P2");
      assert.equal(sim.hashHex(), f.hash, "final hash");
      assert.equal(sim.hash(), BigInt("0x" + f.hash));
      assert.deepEqual(counts, f.eventCounts, "event counts by type");
      assert.equal(eventCount, f.eventCount);
      assert.equal(eventsHash, f.eventsHash, "the event stream");
      assert.deepEqual(log.toWire(0), c.wire.p1, "InputLog.ToWire(0)");
      assert.deepEqual(log.toWire(1), c.wire.p2, "InputLog.ToWire(1)");

      if (c.replay) {
        // The verifier: the setup again, and only the wire log.
        const r = InputLog.replay(setupFrom(c.setup), InputLog.fromWire(0, c.wire.p1));
        assert.deepEqual(
          { hash: r.hashHex, winner: r.winner, ticks: r.ticks, p1Hp: r.p1Hp, p2Hp: r.p2Hp, endReason: r.endReason },
          c.replay,
        );
      }
      if (c.finishJson) {
        assert.equal(finishJson(sim, log), c.finishJson, "the finish body, byte for byte");
        assert.deepEqual(finishPayload(sim, log), JSON.parse(c.finishJson));
      }
    });
  }
});

describe("server setups map exactly as the Unity bridge maps them", () => {
  for (const c of golden.cases.filter((x) => x.server)) {
    const srv = c.server!;
    it(`${c.name}: from parsed JSON plus seed_text`, () => {
      // What the app has: JSON.parse'd (the seed rounded) and the exact digits.
      const lossy = JSON.parse(srv.json) as unknown;
      assert.deepEqual(setupToJson(setupFromServer(lossy, srv.seedText)), c.setup);
      assert.deepEqual(setupToJson(setupFromServer(lossy, BigInt(srv.seedText))), c.setup);
      assert.deepEqual(presentationFromServer(lossy), srv.presentation);
    });
    it(`${c.name}: from the raw JSON text`, () => {
      assert.deepEqual(setupToJson(setupFromServer(srv.json)), c.setup);
      assert.deepEqual(presentationFromServer(srv.json), srv.presentation);
    });
    it(`${c.name}: a rounded seed is refused, never used`, () => {
      const lossy = JSON.parse(srv.json) as { seed: number };
      if (Number.isSafeInteger(lossy.seed)) return; // small seeds survive JSON.parse
      assert.throws(() => setupFromServer(lossy), /seed_text|not exact/);
    });
  }
});
